$ErrorActionPreference = "Stop"
$root = (Get-Location).Path
$backup = Join-Path $root (".security-backup/" + [guid]::NewGuid().ToString())
if ((Get-FileHash -LiteralPath (Join-Path $root "agent/prompts.py")).Hash -ne "ab92bc164dc1b135ff4f8066621739317f863daa644ca8b11d522a7cd3fc7fb8") { throw "Original file differs: agent/prompts.py" }
if ((Get-FileHash -LiteralPath (Join-Path $root "app.py")).Hash -ne "8efc46546e37f4c2467597813e8a8de637d2ba132550f3ae10537de9a2f27713") { throw "Original file differs: app.py" }
if ((Get-FileHash -LiteralPath (Join-Path $root "agent/nodes.py")).Hash -ne "b99db43a346f35d9a606aa834b65de37ef0f116515b7735005992614959ac9be") { throw "Original file differs: agent/nodes.py" }
if ((Get-FileHash -LiteralPath (Join-Path $root "tests/test_graph.py")).Hash -ne "18f0bdb57488d7c27cbf7b9f19c87e882f2528aff1bbd8a6211567405e6bd8bb") { throw "Original file differs: tests/test_graph.py" }
try {
$p = Join-Path $root "agent/prompts.py"
$b = Join-Path $backup "agent/prompts.py"
New-Item -ItemType Directory -Force -Path (Split-Path $b) | Out-Null
Copy-Item -LiteralPath $p -Destination $b
[IO.File]::WriteAllBytes($p,[Convert]::FromBase64String(""))
$p = Join-Path $root "app.py"
$b = Join-Path $backup "app.py"
New-Item -ItemType Directory -Force -Path (Split-Path $b) | Out-Null
Copy-Item -LiteralPath $p -Destination $b
[IO.File]::WriteAllBytes($p,[Convert]::FromBase64String(""))
$p = Join-Path $root "agent/nodes.py"
$b = Join-Path $backup "agent/nodes.py"
New-Item -ItemType Directory -Force -Path (Split-Path $b) | Out-Null
Copy-Item -LiteralPath $p -Destination $b
[IO.File]::WriteAllBytes($p,[Convert]::FromBase64String(""))
$p = Join-Path $root "tests/test_graph.py"
$b = Join-Path $backup "tests/test_graph.py"
New-Item -ItemType Directory -Force -Path (Split-Path $b) | Out-Null
Copy-Item -LiteralPath $p -Destination $b
[IO.File]::WriteAllBytes($p,[Convert]::FromBase64String(""))
& .\.venv\Scripts\python.exe -m pytest -q
if ($LASTEXITCODE -ne 0) { throw "Tests failed" }
} catch {
if (Test-Path (Join-Path $backup "agent/prompts.py")) { Copy-Item -LiteralPath (Join-Path $backup "agent/prompts.py") -Destination (Join-Path $root "agent/prompts.py") -Force }
if (Test-Path (Join-Path $backup "app.py")) { Copy-Item -LiteralPath (Join-Path $backup "app.py") -Destination (Join-Path $root "app.py") -Force }
if (Test-Path (Join-Path $backup "agent/nodes.py")) { Copy-Item -LiteralPath (Join-Path $backup "agent/nodes.py") -Destination (Join-Path $root "agent/nodes.py") -Force }
if (Test-Path (Join-Path $backup "tests/test_graph.py")) { Copy-Item -LiteralPath (Join-Path $backup "tests/test_graph.py") -Destination (Join-Path $root "tests/test_graph.py") -Force }
throw
}
Write-Host "Update complete. Backup: $backup"
